const linearStrainCompatibilityInColumn=(r,n,e)=>{let o;if(null==r||null==n||null==e)throw new Error("Values cannot be empty, null or undefined.");if(isNaN(r)||isNaN(n)||isNaN(e))throw new Error("All input values (d, Xu, x) must be numbers.");if(r<0||n<0||e<0)throw new Error("Values of d, Xu and x cannot be negative.");if(r<=0)throw new Error("d should be greater than zero.");if(n<=r)return o=.0035*(1-e/n),o;if(n>r)return o=.002*(n-e)/(n-3/7*r),o;throw Error("Unknown Error is encountered")};